function updateToolSummary(){const picked=[...$('agent-tools').querySelectorAll('input:checked')].map(i=>i.value);$('agent-tools-summary').textContent='Tools · '+(picked.length?picked.length+' selected: '+picked.map(t=>t.split('__')[1]?.replaceAll('_',' ')||t).join(', '):'none selected');}
$('agent-tools').addEventListener('change',updateToolSummary);
bind('agent-draft',async()=>{const task=$('agent-task').value.trim();if(task.length<10){$('agent-error').textContent='Describe the task in a sentence or two.';$('agent-task').focus();return;}const b=$('agent-draft');b.disabled=true;b.textContent='Setting up…';$('agent-error').textContent='';
  try{const d=await api('/workflows/agents/draft','POST',{task,connectors:chosenConnectors()});await reviewDraft(d);announce('Drafted with '+d.model+' for about $'+Number(d.estimatedUsd).toFixed(4)+'. Check it, then create.');}catch(err){$('agent-error').textContent=err.message;}finally{b.disabled=!state.options?.configured;b.textContent='Set up agent →';}});
bind('agent-manual',()=>reviewDraft({instructions:$('agent-task').value.trim(),tools:[],fields:[]}));
bind('agent-back',()=>agentStep(false));
function setWorkflow(d){if(location.hash.startsWith('#workflows/'))location.hash='workflows';state.workflow=structuredClone(d);state.selectedNode=null;state.connection=null;state.dirty=false;clearRun();$('workflow-name').value=d.name;renderPicker();renderCanvas();}
function newWorkflow(){setWorkflow({id:null,name:'My agent team',nodes:[],edges:[]});location.hash='workflows';}
function addNode(handle){if(state.workflow.nodes.some(n=>n.agent===handle))return;const item=state.agents.find(a=>a.agent.handle===handle);state.workflow.nodes.push({id:'node-'+crypto.randomUUID().slice(0,8),agent:handle,skill:item.skill,x:.33,y:state.workflow.nodes.length?Math.min(4800,Math.max(...state.workflow.nodes.map(n=>n.y))+210):20});edited();renderCanvas();}
function openLibrary(){if(!needConnection())return;const c=$('library-choices');c.replaceChildren();for(const item of state.agents){if(state.workflow.nodes.some(n=>n.agent===item.agent.handle))continue;const b=button('',()=>{addNode(item.agent.handle);$('library-dialog').close();},'library-choice');b.append(node('strong',item.agent.name),node('small',item.agent.function));c.append(b);}if(!c.children.length)c.append(node('p','Create a new agent to add it here.'));$('library-dialog').showModal();}
function connect(from,to){if(state.run)return;if(from===to){announce('Choose a different agent as the receiver.',true);return;}if(state.workflow.edges.some(e=>e.from===from&&e.to===to))return;const edges=[...state.workflow.edges,{from,to,output:'result',input:'upstreamResults'}];const visit=new Set(),active=new Set();function cycle(id){if(active.has(id))return true;if(visit.has(id))return false;active.add(id);for(const e of edges.filter(e=>e.from===id))if(cycle(e.to))return true;active.delete(id);visit.add(id);return false;}if(state.workflow.nodes.some(n=>cycle(n.id))){announce('That connection creates circular waiting. Choose another receiver.',true);return;}state.workflow.edges=edges;edited();renderCanvas();announce('Connected: '+nameOf(state.workflow.nodes.find(n=>n.id===from))+' → '+nameOf(state.workflow.nodes.find(n=>n.id===to))+'.');return true;}
