  content.append(node('p',a?.function||r?.function||'','node-function'),node('span',r?.result?.report?.needsInput?'Needs information':r?.status||(deps.length?'Waits for '+deps.length+' input'+(deps.length>1?'s':''):'Starts first'),'pill '+(r?.result?.report?.needsInput?'needs-input':r?.status||'')));
