async function stopRun(id){await api('/workflows/runs/'+encodeURIComponent(id)+'/stop','POST',{});announce('Run stopped. An agent that was working stops before its next step; nothing more is posted.');if(state.run?.id===id)await openRun(id);if(state.page==='runs')await loadRuns();}
