$('agent-form').addEventListener('submit',async e=>{e.preventDefault();const submit=$('agent-create'),err=$('agent-error');err.textContent='';
  const name=$('agent-name').value.trim(),purpose=$('agent-purpose').value.trim();if(!name||!purpose){err.textContent='Give the agent a name and a one-sentence purpose.';($('agent-name').value.trim()?$('agent-purpose'):$('agent-name')).focus();return;}
  const body={name,function:purpose,model:$('agent-model').value};
  if(state.draft.skill)body.skill=state.draft.skill;else{
    let instructions=$('agent-instructions').value.trim();if(!instructions){err.textContent='Instructions are required: say what to read and what to return.';$('agent-instructions').focus();return;}
    // A confirmed value replaces its {key}; a cleared one is asked for when each run starts.
    const ask=[];for(const i of $('agent-questions').querySelectorAll('[data-key]')){const v=i.value.trim(),k='{'+i.dataset.key+'}';if(v)instructions=instructions.replaceAll(k,v);else{ask.push(i.dataset.question);instructions=instructions.replaceAll(k,'the run input “'+i.dataset.question+'”');}}
    const tools=[...$('agent-tools').querySelectorAll('input:checked')].map(i=>i.value);
    if(state.draft.connectors?.length&&!tools.length){err.textContent='Tick at least one tool, or go back and untick the connector.';$('agent-tools-box').open=true;return;}
    Object.assign(body,{instructions,tools,inputs:ask});}
  submit.disabled=true;try{const created=await api('/workflows/agents','POST',body);await loadPrivate();$('agent-dialog').close();if(state.page==='workflows')addNode(created.agent.handle);else{location.hash='agents';renderAgents();}announce(name+' created. Add it to a workflow and run it.');}catch(e2){err.textContent=e2.message;}finally{submit.disabled=false;}});
