function openSkill(skill,agentName){state.editingSkill=skill?.id||null;$('skill-title').textContent=agentName?'Edit '+agentName:skill?'Edit skill':'Create a reusable skill';$('skill-name').value=skill?.name||'';$('skill-instructions').value=skill?.instructions||'';$('skill-inputs').value=(skill?.inputs||[]).join('\n');renderToolPicker($('skill-tools'),new Set(skill?.permittedTools||[]));$('skill-error').textContent='';$('skill-dialog').showModal();}
function renderSkills(){const list=$('skill-library');list.replaceChildren();if(!state.connected)return;const demo=new Set(state.agents.filter(a=>a.example).map(a=>a.skill));const shared=state.skills.filter(s=>!s.operation&&!s.id.startsWith('for-')&&!demo.has(s.id));if(!shared.length){list.append(node('p','No shared skills. Agents keep their own instructions; create a skill only when several agents should share one.','hint'));return;}
  for(const skill of shared){const users=state.agents.filter(a=>a.skill===skill.id).length,row=node('article',undefined,'row-item');const text=node('div',undefined,'row-text');text.append(node('strong',skill.name),node('p',skill.instructions,'row-line'),node('p',toolSummary(skill.permittedTools)+' · used by '+users+' agent'+(users===1?'':'s'),'row-meta'));
    const actions=node('div',undefined,'row-actions');actions.append(button('New agent',()=>openAgent(skill.id),'text-button'),button('Edit',()=>openSkill(skill),'text-button'));if(!users)actions.append(button('Delete',async()=>{if(!confirm('Delete the skill '+skill.name+'?'))return;await api('/workflows/skills/'+encodeURIComponent(skill.id),'DELETE');await loadPrivate();announce('Skill deleted.');},'text-button danger'));
    row.append(node('span','◇','avatar small skill'),text,actions);list.append(row);}}
