function short(text,max){text=String(text||'');return text.length>max?text.slice(0,max-1)+'…':text;}
/** Plain-language reason for a failed agent; the console keeps the raw detail. */
function explain(error){const e=String(error||'');
  if(/Stopped by a person|run was stopped/.test(e))return 'you stopped the run.';
  if(/without a single successful connector tool call/.test(e))return 'every tool call it made failed, so it had nothing real to report. Open the console for each error; usually the agent had to guess a value (such as a branch name). Edit the agent to name it, or add a question asked at run start.';
  if(/Invalid report structure/.test(e))return 'the report validator rejected the output. In older runs this included honest empty findings when no source information was supplied. Inspect Evidence for the original model response.';
  if(/required source evidence/.test(e))return 'it could not read its required sources ('+(e.match(/\[(.*)\]/)?.[1]||'tools')+'). Open the console to see each tool call and its error.';
  if(/OPENAI_API_KEY|401|invalid_api_key/i.test(e))return 'OpenAI rejected the request: check OPENAI_API_KEY in .env and restart the board.';
  if(/budget|allowance|max-calls|attempt cap/i.test(e))return 'the OpenAI spending cap for this board was reached. Raise BOARD_OPENAI_BUDGET_USD or BOARD_OPENAI_MAX_CALLS in .env.';
  if(/rate limit|403|API rate/i.test(e))return 'GitHub refused the request (rate limit or access). Add GITHUB_TOKEN to .env.';
  if(/404|Not Found/i.test(e))return 'the repository, issue or file was not found. Check the run parameters.';
  return e||'no reason was recorded.';}
function clock(t){if(!t)return '        ';const d=new Date(t);return isNaN(d)?'        ':d.toLocaleTimeString([], {hour12:false});}
function logLine(box,time,text,kind,tip){const row=node('div',undefined,'log-line '+(kind||''));row.append(node('span',clock(time),'ts'),node('span',text,'msg'));if(tip)row.title=tip;box.append(row);return row;}
async function openConsole(run,focus){
  const log=$('console-log'),why=$('console-why');$('console-title').textContent=run.name+' · '+run.status;log.replaceChildren();why.hidden=true;
  logLine(log,null,'Loading the run log…','muted');if(!$('console-dialog').open)$('console-dialog').showModal();
  const parts=await Promise.all(run.nodes.map(async n=>{if(!n.runId)return{n};const[r,ev]=await Promise.all([api('/runs/'+n.runId).catch(()=>null),api('/workflows/evidence/'+n.runId).catch(()=>null)]);return{n,r,report:ev?.report};}));
  log.replaceChildren();
  logLine(log,run.createdAt,'Workflow "'+run.name+'" run '+run.id.slice(0,8)+' · '+run.provider,'head');
  const params=Object.entries(run.parameters||{}).map(([k,v])=>k+'='+v).join(' · ');if(params)logLine(log,null,'Parameters: '+params,'muted');
  const failed=parts.filter(p=>p.n.status==='failed');
  if(failed.length){why.replaceChildren(node('strong','Why this run failed'));const ul=node('ul');for(const f of failed)ul.append(node('li',f.n.name+': '+explain(f.n.error)));why.append(ul);why.hidden=false;}
  for(const{n,r,report}of parts){
    const sec=node('details',undefined,'log-section '+(n.status||''));sec.open=!focus||focus===n.node||n.status==='failed';
    const sum=node('summary');sum.append(node('span',n.status||'not started','pill '+(n.status||'')),node('strong',' '+n.name),node('span',(n.runId?'  run #'+n.runId:'')+(r?.durationMs!=null?' · '+(r.durationMs/1000).toFixed(1)+' s':'')+(n.model?' · '+n.model:''),'muted'));sec.append(sum);
    const box=node('div',undefined,'log-body');sec.append(box);log.append(sec);
    if(!n.runId){logLine(box,null,n.waitingFor?.length?'Not started: waiting for '+n.waitingFor.join(', ')+', which did not finish.':'Not started.',n.status==='blocked'?'warn':'muted');continue;}
    if(r?.queuedAt)logLine(box,r.queuedAt,'Queued');
    if(r?.startedAt)logLine(box,r.startedAt,'Started on worker '+(r.worker||'?'));
    for(const st of(r?.steps||[]).filter(st=>st.stage==='observe'))logLine(box,null,'Input '+st.name+': '+st.detail,st.status==='ok'?'ok':'fail');
    if(report){
      if(report.parameters&&Object.keys(report.parameters).length)logLine(box,report.startedAt,'Model '+report.model+' given parameters '+JSON.stringify(report.parameters),'muted');
      const events=[...(report.responses||[]).map(x=>({t:x.receivedAt,kind:'response',x})),...(report.toolCalls||[]).map(x=>({t:x.startedAt,kind:'tool',x}))].sort((a,b)=>String(a.t).localeCompare(String(b.t)));
      for(const ev of events){const x=ev.x;
        if(ev.kind==='response'){const u=x.usage||{},calls=(x.output||[]).filter(o=>o.type==='function_call').map(o=>o.name),text=(x.output||[]).some(o=>o.type==='message');
          logLine(box,x.receivedAt,'OpenAI replied ('+(u.input_tokens??'?')+' in / '+(u.output_tokens??'?')+' out tokens'+(x.estimatedUsd!=null?', ~$'+Number(x.estimatedUsd).toFixed(5):'')+')'+(calls.length?' → asks to call '+calls.join(', '):text?' → final answer':''),'info',x.responseId);}
        else{const args=x.arguments&&Object.keys(x.arguments).length?JSON.stringify(x.arguments):'';
          if(x.status==='success')logLine(box,x.startedAt,'Tool '+x.tool+'('+args+') → ok','ok',short(JSON.stringify(x.result||''),600));
          else logLine(box,x.startedAt,'Tool '+x.tool+'('+args+') → FAILED: '+(x.error||'unknown error'),'fail');}}
      if(report.evidence?.length)logLine(box,null,'Collected '+report.evidence.length+' piece(s) of source evidence','ok');
      const last=[...(report.responses||[])].reverse().find(x=>(x.output||[]).some(o=>o.type==='message'));const answer=last?.output.find(o=>o.type==='message')?.content?.[0]?.text;
      if(answer){try{const a=JSON.parse(answer);if(a.summary)logLine(box,null,'Model summary: '+short(a.summary,400),'muted',a.summary);(a.uncertainties||[]).forEach(u=>logLine(box,null,'Model noted: '+u,'warn'));}catch{logLine(box,null,'Model said: '+short(answer,400),'muted',answer);}}
    }
    for(const st of(r?.steps||[]).filter(st=>st.stage!=='observe'))logLine(box,null,st.stage+' '+st.name+': '+st.detail,st.status==='failed'?'fail':st.status==='ok'?'ok':'info');
    const end=r?.status||n.status;logLine(box,r?.finishedAt,end==='success'?'Finished: SUCCESS':'Finished: '+String(end).toUpperCase()+(n.error?' — '+n.error:''),end==='success'?'ok':'fail');
  }
  logLine(log,null,'Workflow finished: '+String(run.status).toUpperCase(),run.status==='success'||run.status==='completed'?'ok':'fail');
  if(focus)log.querySelector('.log-section[open]')?.scrollIntoView({block:'nearest'});
}
bind('console-copy',async()=>{await navigator.clipboard.writeText([$('console-why').hidden?'':$('console-why').innerText,$('console-log').innerText].join('\n'));announce('Console log copied.');});

/* ---- MCP connectors ---------------------------------------------------------------------------------- */
async function loadConnectors(){state.mcp=await api('/mcp/connectors');renderConnectors();return state.mcp;}
function missingSecretHint(v){return v.connector?.transport==='http'?'Add an access token in Edit, or configure the missing credentials under Advanced headers.':'Missing in .env: '+v.missingSecrets.join(', ')+'. Add them and restart the board.';}
function renderConnectors(){const list=$('connector-list');list.replaceChildren();
  if(!state.mcp?.length){list.append(empty('No connectors yet.','Add one from the list of known MCP servers, or describe your own. Its tools then become available to skills.'));return;}
  for(const v of state.mcp){const c=v.connector,card=node('article',undefined,'connector-card '+v.state);
    const head=node('div',undefined,'connector-head');head.append(node('h3',c.name),node('span',v.state,'pill '+({connected:'success',failed:'failed',connecting:'running'}[v.state]||'')));card.append(head);
    card.append(node('p',(c.transport==='http'?c.url:[c.command,...c.args].join(' ')),'connector-address'));
    if(c.description)card.append(node('p',c.description,'hint'));
    if(v.accessTokenStored)card.append(node('p','Access token saved privately on this server.','hint'));
    if(v.server)card.append(node('p','Server: '+v.server+(v.checkedAt?' · checked '+date(v.checkedAt):''),'hint'));
    if(v.missingSecrets?.length)card.append(node('p',missingSecretHint(v),'connector-warning'));
    if(v.error){const e=node('p',v.error,'node-error');card.append(e);}
    if(v.serverLog?.length){const d=node('details');d.append(node('summary','Server output'),node('pre',v.serverLog.join('\n')));card.append(d);}
    if(v.tools?.length){const d=node('details',undefined,'tool-list');d.append(node('summary',v.tools.length+' tools'));const ul=node('ul');for(const t of v.tools){const li=node('li');li.append(node('code',t.name));if(t.writes)li.append(node('span','writes','pill tool-writes'));li.append(node('span',' '+(t.title||t.description||'').split('\n')[0].slice(0,140),'hint'));li.title=t.description||'';ul.append(li);}d.append(ul);card.append(d);}
    const actions=node('div',undefined,'actions');
    actions.append(button('Test',async()=>{card.classList.add('busy');try{const r=await api('/mcp/connectors/'+c.id+'/test','POST',{});Object.assign(v,r);announce(r.state==='connected'?c.name+' connected: '+r.tools.length+' tools.':c.name+' failed: '+r.error,r.state!=='connected');}finally{renderConnectors();}}),button('Edit',()=>openConnector(c),'text-button'),button('Delete',async()=>{if(!confirm('Delete the connector '+c.name+'?'))return;await api('/mcp/connectors/'+c.id,'DELETE');await loadConnectors();announce('Connector deleted.');},'text-button'));
    card.append(actions);list.append(card);}}
function lines(text){return String(text||'').split('\n').map(l=>l.trim()).filter(Boolean);}
function pairs(text,sep){const out={};for(const l of lines(text)){const i=l.indexOf(sep);if(i<1)throw new Error('Use '+(sep===':'?'Name: value':'NAME=value')+' on each line: '+l);out[l.slice(0,i).trim()]=l.slice(i+1).trim();}return out;}
function showTransport(){const http=$('connector-transport').value==='http';$('connector-http').hidden=!http;$('connector-stdio').hidden=http;}
function fillConnector(c){$('connector-token').value='';$('connector-token-status').textContent=(state.mcp||[]).some(v=>v.connector.id===c?.id&&v.accessTokenStored)?'Token saved. Leave blank to keep it, or paste a replacement.':'Saved privately on this server. No restart needed.';$('connector-name').value=c?.name||'';$('connector-id').value=c?.id||'';$('connector-description').value=c?.description||'';$('connector-transport').value=c?.transport||'http';$('connector-url').value=c?.url||'';$('connector-headers').value=Object.entries(c?.headers||{}).map(([k,v])=>k+': '+v).join('\n');$('connector-command').value=c?.command||'npx';$('connector-args').value=(c?.args||[]).join('\n');$('connector-env').value=Object.entries(c?.env||{}).map(([k,v])=>k+'='+v).join('\n');showTransport();}
async function openConnector(existing,presetId){if(!needConnection())return;state.editingConnector=existing?.id||null;$('connector-title').textContent=existing?'Edit '+existing.name:'Add a connector';$('connector-error').textContent='';$('connector-id').readOnly=!!existing;
  const presets=state.presets||(state.presets=await api('/mcp/presets'));const sel=$('connector-preset');sel.replaceChildren(node('option','Custom server'));sel.firstChild.value='';for(const p of presets){const o=node('option',p.name+' — '+p.description);o.value=p.id;sel.append(o);}sel.disabled=!!existing;fillConnector(existing);const preset=!existing&&presets.find(p=>p.id===presetId);if(preset){sel.value=preset.id;fillConnector(preset);}$('connector-dialog').showModal();}
$('connector-preset').addEventListener('change',()=>{const p=(state.presets||[]).find(x=>x.id===$('connector-preset').value);if(p)fillConnector(p);});
$('connector-transport').addEventListener('change',showTransport);
$('connector-form').addEventListener('submit',async e=>{e.preventDefault();const submit=e.submitter;submit.disabled=true;$('connector-error').textContent='';
  try{const http=$('connector-transport').value==='http';const body={id:$('connector-id').value.trim(),name:$('connector-name').value.trim(),description:$('connector-description').value.trim(),transport:http?'http':'stdio',url:http?$('connector-url').value.trim():null,headers:http?pairs($('connector-headers').value,':'):{},accessToken:http?$('connector-token').value:undefined,command:http?null:$('connector-command').value,args:http?[]:lines($('connector-args').value),env:http?{}:pairs($('connector-env').value,'=')};
    const saved=await api('/mcp/connectors','POST',body);$('connector-token').value='';if(saved.accessTokenStored){$('connector-token-status').textContent='Token saved. Leave blank to keep it, or paste a replacement.';$('connector-headers').value=Object.entries(saved.connector.headers||{}).map(([k,v])=>k+': '+v).join('\n');}submit.textContent='Connecting…';const r=await api('/mcp/connectors/'+body.id+'/test','POST',{});
    await loadConnectors();
    if(r.state==='connected'){$('connector-dialog').close();announce(body.name+' connected: '+r.tools.length+' tools are now available to skills.');}
    else $('connector-error').textContent='Saved, but it did not connect: '+(r.error||'unknown error')+(r.missingSecrets?.length?' '+missingSecretHint(r):'');
  }catch(err){$('connector-error').textContent=err.message;}finally{submit.disabled=false;submit.textContent='Save and test';}});
$('connector-dialog').addEventListener('close',()=>{$('connector-token').value='';});
bind('new-connector',()=>openConnector());
/** Tool checkboxes grouped by connector; `only` limits the list to some connectors. */
async function renderToolPicker(box,chosen,only){box.replaceChildren(node('p','Loading tools…','hint'));
  function option(value,text,tip,writes){const label=node('label'),input=node('input');input.type='checkbox';input.value=value;input.checked=chosen.has(value);label.append(input,node('span',text));if(writes)label.append(node('span','writes','pill tool-writes'));if(tip)label.title=tip;return label;}
  let connectors=[];try{connectors=await loadConnectors();}catch{}box.replaceChildren();
  // Connectors already used by the chosen tools stay visible, so editing never hides a selection.
  const keep=new Set([...chosen].map(t=>t.split('__')[0]));if(only)connectors=connectors.filter(v=>only.includes(v.connector.id)||keep.has(v.connector.id));
  for(const v of connectors){const g=node('fieldset',undefined,'tool-group');g.append(node('legend',v.connector.name+(v.state==='connected'?'':' · '+v.state)));
    if(v.state!=='connected')g.append(node('p',v.error||'Test this connector on the Connectors page to list its tools.','hint'));
    const tools=[...(v.tools||[])].sort((a,b)=>(chosen.has(b.qualifiedName)-chosen.has(a.qualifiedName))||(a.writes-b.writes)||a.name.localeCompare(b.name));
    for(const t of tools)g.append(option(t.qualifiedName,t.name.replaceAll('_',' '),t.description,t.writes));
    box.append(g);}
  if(!connectors.length)box.append(node('p',only?'No connector chosen: this agent works on results from other agents and text pasted when a run starts.':'Add a connector on the Connectors page to give skills tools from GitHub, Notion, the web and more.','hint'));
}
// Demo tab: the workflow made only of example agents (examples/), shown step by step.
function demoWorkflow(){const ex=new Set(state.agents.filter(a=>a.example).map(a=>a.agent.handle));return state.definitions.find(d=>d.nodes.length&&d.nodes.every(n=>ex.has(n.agent)));}
function renderDemo(){const box=$('demo-stages'),d=demoWorkflow();box.replaceChildren();$('demo-open').disabled=$('demo-run').disabled=!d;const note=$('demo-note');note.hidden=true;
  if(!state.connected){box.append(empty('Connect to see the demo.','Use the Local workspace control to enter your board token.'));return;}
  if(!d){box.append(empty('The demo is not loaded.','Start the board with bash start.sh to load the ten example agents and their workflow.'));return;}
  $('demo-title').textContent=d.name;
  const needed=[...new Set(d.nodes.flatMap(n=>state.skills.find(s=>s.id===n.skill)?.permittedTools||[]).map(t=>t.split('__')[0]))],have=new Set((state.options?.tools||[]).map(t=>t.split('__')[0])),missing=needed.filter(c=>!have.has(c));
  if(missing.length){note.hidden=false;note.replaceChildren(node('span','The demo needs the '+missing.map(c=>c==='github'?'GitHub':c).join(', ')+' connector. Paste a GitHub token (read-only is enough) and press Save and test. '),button('Add the GitHub connector →',()=>addDemoConnector(missing[0]),'button'));}
  const depth=new Map();const level=id=>{if(depth.has(id))return depth.get(id);depth.set(id,0);const v=Math.max(0,...d.edges.filter(e=>e.to===id).map(e=>level(e.from)+1));depth.set(id,v);return v;};d.nodes.forEach(n=>level(n.id));
  const names=['Read the repository','Connect the findings','Judge','Write it up'],max=Math.max(...depth.values());
  for(let i=0;i<=max;i++){box.append(node('h3',(i+1)+'. '+(names[i]||'Step '+(i+1)),'list-title'));const list=node('div',undefined,'row-list');
    for(const n of d.nodes.filter(n=>depth.get(n.id)===i)){const item=state.agents.find(a=>a.agent.handle===n.agent),a=item.agent,s=state.skills.find(s=>s.id===n.skill),row=node('article',undefined,'row-item'),text=node('div',undefined,'row-text');
      const to=d.edges.filter(e=>e.from===n.id).map(e=>nameOf(d.nodes.find(x=>x.id===e.to)));
      text.append(node('strong',a.name),node('p',a.function,'row-line'),node('p',toolSummary(s?.permittedTools)+(to.length?' · sends its result to '+to.join(', '):''),'row-meta'));
      const actions=node('div',undefined,'row-actions');actions.append(button('Profile',()=>showAgent(item),'text-button'));row.append(node('span',initials(a.name),'avatar small'),text,actions);list.append(row);}
    box.append(list);}}
function openDemo(){const d=demoWorkflow();if(!d)return false;setWorkflow(structuredClone(d));location.hash='workflows';return true;}
