// Opens the connector the demo needs: its existing entry if there is one (to paste a token), else a new one from the preset.
async function addDemoConnector(id){location.hash='connectors';const list=await loadConnectors();const existing=list.find(v=>v.connector.id===id);await openConnector(existing?.connector,id);}
// Docs check: runs DocDrift (src/docdrift) on a GitHub repository and shows its findings; the result is also posted to the feed.
let docsTimer=null;
async function loadDocs(){clearTimeout(docsTimer);const data=await api('/docdrift');const box=$('docs-runs');box.replaceChildren();$('docs-run').disabled=!data.available||data.runs.some(r=>r.status==='running');
  if(!data.available){box.append(empty('Docs check is not available here.','It needs the repository folder and python3: start the board with bash start.sh.'));return;}
  if(!data.runs.length){box.append(empty('No checks yet.','Press Run check: pallets/click from 8.1.8 to main finds six outdated places in about 15 seconds.'));return;}
  for(const r of data.runs){const card=node('article',undefined,'docs-run'),head=node('div',undefined,'docs-run-head');
    head.append(node('strong',r.repo+' · '+r.base+' → '+r.head),node('span',r.status,'pill '+(r.status==='done'?'success':r.status)),node('small',date(r.startedAt)));card.append(head);
    const s=r.summary;
    if(s)card.append(node('p',s.api_changes+' API changes. '+s.doc_references+' places in the docs still use the old API: '+s.outdated+' outdated, '+s.auto_fixed+' fixed automatically, '+s.needs_person+' need a person. Judged by '+s.reasoner+' · '+s.model_calls+' model calls · '+s.seconds+' s.','docs-summary'));
    if(r.findings?.length){const t=node('table',undefined,'docs-table'),hr=node('tr');for(const h of ['Where','What changed','Verdict','Fix'])hr.append(node('th',h));t.append(hr);
      for(const f of r.findings){const tr=node('tr');tr.append(node('td',f.where,'mono'),node('td',f.change),node('td',(f.outdated===null?'not reviewed':f.outdated?'Outdated: ':'Fine: ')+(f.reason||'')),node('td',f.fixed?'✅ fixed in the patch':f.blocked.length?'Needs a person: '+f.blocked.join('; '):'Needs a person'));t.append(tr);}
      card.append(t);}
    else if(r.status==='done'&&s&&!s.doc_references)card.append(node('p','No doc uses a changed API. The docs are current for this range.','docs-summary'));
    if(r.status!=='done'&&r.output?.length){const d=node('details');d.open=r.status==='failed'||r.status==='running';d.append(node('summary',r.status==='running'?'Progress':'Output'),node('pre',r.output.join('\n')));card.append(d);}
    if(r.status==='done'){const a=node('a','See the post in the feed →','text-button');a.href='#feed';card.append(a);}
    box.append(card);}
  if(data.runs.some(r=>r.status==='running')&&state.page==='docs')docsTimer=setTimeout(()=>loadDocs().catch(error),2000);}
$('docs-form').addEventListener('submit',async e=>{e.preventDefault();$('docs-error').textContent='';$('docs-run').disabled=true;
  try{await api('/docdrift/runs','POST',{repo:$('docs-repo').value.trim(),base:$('docs-base').value.trim(),head:$('docs-head').value.trim(),reasoner:$('docs-reasoner').value});await loadDocs();}
  catch(err){$('docs-error').textContent=err.message;$('docs-run').disabled=false;}});
